CREATE TABLE demand_sync_sources(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,name TEXT NOT NULL,url TEXT NOT NULL,doc_id TEXT NOT NULL,tab_id TEXT NOT NULL,title TEXT NOT NULL DEFAULT '',interval_minutes INTEGER NOT NULL DEFAULT 30 CHECK(interval_minutes BETWEEN 1 AND 1440),enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)),media_id TEXT REFERENCES partners(id),sale_project TEXT NOT NULL DEFAULT 'UNKNOWN' CHECK(sale_project IN ('KA','MEMBER','UNKNOWN')),headers TEXT NOT NULL DEFAULT '[]',last_success_at TEXT,last_attempt_at TEXT,next_run_at TEXT NOT NULL,last_error TEXT NOT NULL DEFAULT '',running_until TEXT,run_id TEXT,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,UNIQUE(org_id,doc_id,tab_id));
CREATE TABLE demand_sync_runs(id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES demand_sync_sources(id),org_id TEXT NOT NULL,trigger_kind TEXT NOT NULL,status TEXT NOT NULL,started_at TEXT NOT NULL,finished_at TEXT,fetched INTEGER NOT NULL DEFAULT 0,added INTEGER NOT NULL DEFAULT 0,updated INTEGER NOT NULL DEFAULT 0,unchanged INTEGER NOT NULL DEFAULT 0,removed INTEGER NOT NULL DEFAULT 0,error TEXT NOT NULL DEFAULT '');
CREATE TABLE demand_sync_projects(id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES demand_sync_sources(id),org_id TEXT NOT NULL,source_key TEXT NOT NULL,row_number INTEGER NOT NULL,values_json TEXT NOT NULL,raw_json TEXT NOT NULL,content_hash TEXT NOT NULL,is_present INTEGER NOT NULL DEFAULT 1,first_seen_at TEXT NOT NULL,last_seen_at TEXT NOT NULL,changed_at TEXT NOT NULL,UNIQUE(source_id,source_key));
CREATE INDEX demand_sync_due ON demand_sync_sources(enabled,next_run_at);
CREATE INDEX demand_sync_project_source ON demand_sync_projects(org_id,source_id,is_present,row_number);
INSERT INTO schema_version VALUES(16,datetime('now'));
